async function runCli() {
  const rows = [];
  const preflight = await backendPreflight();
  if (!preflight) {
    const report = {
      complete: false,
      pec: { state: defaultTargets.pec.state },
      rows: [
        {
          target: 'backend.healthz',
          result: 'failed',
          reason: 'backend_unreachable',
          status: 0,
        },
      ],
    };
    await writeReport(report);
    return report;
  }

